node -e "const { TokenBucket } = require('./kova.js');

// Test 1: Basic construction and starts full
const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 5 });
console.log('Test 1 - Initial available:', bucket.available() === 10 ? 'PASS' : 'FAIL');

// Test 2: tryTake succeeds when enough tokens
console.log('Test 2 - tryTake(3):', bucket.tryTake(3) === true ? 'PASS' : 'FAIL');
console.log('Test 2 - available after take:', bucket.available() === 7 ? 'PASS' : 'FAIL');

// Test 3: tryTake fails when not enough tokens
const bucket2 = new TokenBucket({ capacity: 5, refillPerSecond: 1 });
console.log('Test 3 - tryTake(10):', bucket2.tryTake(10) === false ? 'PASS' : 'FAIL');
console.log('Test 3 - available unchanged:', bucket2.available() === 5 ? 'PASS' : 'FAIL');

// Test 4: Refill over time with fake clock
let time = 1000;
const bucket3 = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => time });
bucket3.tryTake(10); // empty
console.log('Test 4a - Empty after take:', bucket3.available() === 0 ? 'PASS' : 'FAIL');
time += 500; // 0.5 seconds
console.log('Test 4b - After 0.5s:', bucket3.available() === 5 ? 'PASS' : 'FAIL');
time += 500; // 1 second total
console.log('Test 4c - After 1s:', bucket3.available() === 10 ? 'PASS' : 'FAIL');

// Test 5: msUntil
const bucket4 = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => time });
bucket4.tryTake(10);
console.log('Test 5a - msUntil(5) at empty:', bucket4.msUntil(5) === 500 ? 'PASS' : 'FAIL');
console.log('Test 5b - msUntil(10) at empty:', bucket4.msUntil(10) === 1000 ? 'PASS' : 'FAIL');
console.log('Test 5c - msUntil(1) when full:', bucket4.msUntil(1) === 0 ? 'PASS' : 'FAIL');

// Test 6: n > capacity returns Infinity
const bucket5 = new TokenBucket({ capacity: 10, refillPerSecond: 10 });
console.log('Test 6 - msUntil(11):', bucket5.msUntil(11) === Infinity ? 'PASS' : 'FAIL');

// Test 7: refillPerSecond = 0, not enough tokens -> Infinity
const bucket6 = new TokenBucket({ capacity: 10, refillPerSecond: 0 });
bucket6.tryTake(10);
console.log('Test 7 - msUntil(1) with 0 refill:', bucket6.msUntil(1) === Infinity ? 'PASS' : 'FAIL');

// Test 8: Clock going backwards doesn't remove tokens
let time2 = 1000;
const bucket7 = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => time2 });
bucket7.tryTake(5); // 5 left
time2 += 1000; // 1s passes, refill to 10
console.log('Test 8a - After 1s:', bucket7.available() === 10 ? 'PASS' : 'FAIL');
time2 = 500; // clock goes back
console.log('Test 8b - Clock back, available:', bucket7.available() === 10 ? 'PASS' : 'FAIL');
time2 = 2000; // clock jumps forward from original
console.log('Test 8c - Clock forward from max:', bucket7.available() === 10 ? 'PASS' : 'FAIL');

// Test 9: Validation errors
try { new TokenBucket({ capacity: 0, refillPerSecond: 1 }); console.log('Test 9a - capacity 0: FAIL'); } catch(e) { console.log('Test 9a - capacity 0:', e instanceof RangeError ? 'PASS' : 'FAIL'); }
try { new TokenBucket({ capacity: -1, refillPerSecond: 1 }); console.log('Test 9b - capacity -1: FAIL'); } catch(e) { console.log('Test 9b - capacity -1:', e instanceof RangeError ? 'PASS' : 'FAIL'); }
try { new TokenBucket({ capacity: NaN, refillPerSecond: 1 }); console.log('Test 9c - capacity NaN: FAIL'); } catch(e) { console.log('Test 9c - capacity NaN:', e instanceof RangeError ? 'PASS' : 'FAIL'); }
try { new TokenBucket({ capacity: 10, refillPerSecond: -1 }); console.log('Test 9d - refillPerSecond -1: FAIL'); } catch(e) { console.log('Test 9d - refillPerSecond -1:', e instanceof RangeError ? 'PASS' : 'FAIL'); }
try { new TokenBucket({ capacity: 10, refillPerSecond: NaN }); console.log('Test 9e - refillPerSecond NaN: FAIL'); } catch(e) { console.log('Test 9e - refillPerSecond NaN:', e instanceof RangeError ? 'PASS' : 'FAIL'); }
try { bucket5.tryTake(0); console.log('Test 9f - tryTake(0): FAIL'); } catch(e) { console.log('Test 9f - tryTake(0):', e instanceof RangeError ? 'PASS' : 'FAIL'); }
try { bucket5.tryTake(-1); console.log('Test 9g - tryTake(-1): FAIL'); } catch(e) { console.log('Test 9g - tryTake(-1):', e instanceof RangeError ? 'PASS' : 'FAIL'); }
try { bucket5.msUntil(0); console.log('Test 9h - msUntil(0): FAIL'); } catch(e) { console.log('Test 9h - msUntil(0):', e instanceof RangeError ? 'PASS' : 'FAIL'); }
try { bucket5.msUntil(-1); console.log('Test 9i - msUntil(-1): FAIL'); } catch(e) { console.log('Test 9i - msUntil(-1):', e instanceof RangeError ? 'PASS' : 'FAIL'); }

// Test 10: Fractional refill
let time3 = 0;
const bucket8 = new TokenBucket({ capacity: 10, refillPerSecond: 3, now: () => time3 });
bucket8.tryTake(10);
time3 = 1000; // 1 second -> 3 tokens
console.log('Test 10 - Fractional refill:', bucket8.available() === 3 ? 'PASS' : 'FAIL');

console.log('All tests completed');
"

node -e "const { TokenBucket } = require('./kova.js');

// Verify Test 5c - msUntil when actually full
let time = 2000;
const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: () => time });
console.log('Available when full:', bucket.available()); // should be 10
console.log('msUntil(1) when full:', bucket.msUntil(1)); // should be 0
console.log('msUntil(5) when full:', bucket.msUntil(5)); // should be 0
console.log('msUntil(10) when full:', bucket.msUntil(10)); // should be 0
console.log('msUntil(11) when full:', bucket.msUntil(11)); // should be Infinity

// Also test msUntil rounding up
let time2 = 0;
const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 3, now: () => time2 });
bucket2.tryTake(10);
time2 = 100; // 0.1s -> 0.3 tokens, need 1 token = 0.333s = 333.33ms -> ceil 334
console.log('msUntil(1) at 100ms:', bucket2.msUntil(1));

// Test fractional tokens available
let time3 = 0;
const bucket3 = new TokenBucket({ capacity: 10, refillPerSecond: 3, now: () => time3 });
bucket3.tryTake(9.5);
console.log('Available after taking 9.5:', bucket3.available());
console.log('tryTake(0.6):', bucket3.tryTake(0.6));
console.log('Available after:', bucket3.available());
"
